//! Values are generated by Python float.hex/struct, not by the production parser.

#[test]
fn matches_python_ieee_conversion_vectors() -> Result<(), Box<dyn std::error::Error>> {
    let vectors: serde_json::Value = serde_json::from_str(include_str!("python-vectors.json"))?;
    let vectors = vectors.as_array().ok_or("missing reference vector array")?;
    assert_eq!(vectors.len(), 256);
    for vector in vectors {
        let text = vector["hex"].as_str().ok_or("missing literal")?;
        let bits = u64::from_str_radix(vector["bits"].as_str().ok_or("missing bit pattern")?, 16)?;
        let actual = match vector["width"].as_u64() {
            Some(32) => u64::from(hexf_parse::parse_hexf32(text, false)?.to_bits()),
            Some(64) => hexf_parse::parse_hexf64(text, false)?.to_bits(),
            _ => return Err("invalid reference width".into()),
        };
        assert_eq!(actual, bits, "{text}");
    }
    Ok(())
}
